window.QBANK["m5w2"] = [
  {"level": 1, "q": "Trong kiến trúc ứng dụng LLM, \"workflow\" là gì?", "options": ["Hệ thống mà code định sẵn các bước, LLM thực hiện từng bước theo luồng đã lập trình", "Hệ thống mà LLM tự quyết định bước tiếp theo và tự chọn tool", "Một file YAML của GitHub Actions", "Một model được fine-tune riêng"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Ở workflow, luồng điều khiển nằm trong code; LLM chỉ là một thành phần trong từng bước.<br><strong>Vì sao các lựa chọn khác sai:</strong> LLM tự quyết bước tiếp theo là định nghĩa của agent; YAML GitHub Actions chỉ trùng tên; fine-tune không liên quan tới kiến trúc điều khiển."},
  {"level": 1, "q": "\"Agent\" khác workflow ở điểm cốt lõi nào?", "options": ["Agent luôn dùng model đắt nhất", "LLM tự quyết định bước tiếp theo và dùng tool trong vòng lặp cho tới khi xong việc", "Agent không bao giờ gọi tool", "Agent chạy không cần prompt"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Điểm phân biệt là ai điều khiển luồng: ở agent, model quyết định gọi tool nào, khi nào dừng.<br><strong>Vì sao các lựa chọn khác sai:</strong> Agent dùng được mọi model; gọi tool trong vòng lặp là bản chất của agent; agent vẫn cần system prompt và nhiệm vụ rõ ràng."},
  {"level": 1, "q": "Nguyên tắc vàng khi chọn kiến trúc cho một tính năng dùng Claude là gì?", "options": ["Bắt đầu đơn giản nhất: một lần gọi API, rồi workflow, chỉ lên agent khi thật cần", "Luôn bắt đầu bằng multi-agent để dễ mở rộng", "Luôn dùng agent vì linh hoạt nhất", "Chọn kiến trúc theo model mới nhất"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Mỗi tầng phức tạp hơn tốn thêm chi phí, độ trễ và khó debug; chỉ nâng tầng khi tầng dưới không đáp ứng được.<br><strong>Vì sao các lựa chọn khác sai:</strong> Multi-agent và agent đắt, khó kiểm soát nếu dùng mặc định; model mới không quyết định kiến trúc."},
  {"level": 1, "q": "Mẫu nào KHÔNG thuộc 5 mẫu workflow phổ biến trong bài học?", "options": ["Prompt chaining", "Fine-tuning loop", "Routing", "Evaluator–optimizer"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Năm mẫu là prompt chaining, routing, parallelization, orchestrator–workers và evaluator–optimizer.<br><strong>Vì sao các lựa chọn khác sai:</strong> Chaining, routing và evaluator–optimizer đều nằm trong danh sách năm mẫu."},
  {"level": 1, "q": "Prompt chaining là gì?", "options": ["Gửi cùng một prompt nhiều lần rồi bỏ phiếu", "Để model tự chia việc cho worker", "Nối nhiều API key để tăng hạn mức", "Chia nhiệm vụ thành chuỗi bước tuần tự, đầu ra bước trước là đầu vào bước sau, có thể có cổng kiểm tra xen giữa"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Chaining đổi độ trễ lấy độ chính xác: mỗi bước đơn giản hơn nên model làm tốt hơn.<br><strong>Vì sao các lựa chọn khác sai:</strong> Chạy nhiều lần rồi bỏ phiếu là voting; model tự chia việc là orchestrator–workers; nối API key không phải mẫu kiến trúc."},
  {"level": 1, "q": "Cổng kiểm tra (gate) giữa các bước trong prompt chaining dùng để làm gì?", "options": ["Kiểm tra kết quả bước trước bằng code hoặc LLM, bắt lỗi sớm trước khi đi tiếp", "Giảm giá token của bước sau", "Là tham số bắt buộc của Messages API", "Tự động song song hoá các bước"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Lỗi ở bước đầu lan sang mọi bước sau; kiểm tra sớm rẻ hơn sửa ở cuối.<br><strong>Vì sao các lựa chọn khác sai:</strong> Gate không đổi giá token; API không có tham số gate; gate không làm các bước chạy song song."},
  {"level": 1, "q": "Routing là mẫu workflow như thế nào?", "options": ["Chạy mọi input qua tất cả các model rồi chọn kết quả tốt nhất", "Để một LLM điều phối nhiều worker", "Phân loại input rồi chuyển tới prompt, model hoặc luồng xử lý chuyên biệt cho từng loại", "Lặp sinh và chấm cho tới khi đạt điểm"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Routing tách mối quan tâm: mỗi loại input có cách xử lý tối ưu riêng, ví dụ câu dễ sang Haiku, câu khó sang Opus.<br><strong>Vì sao các lựa chọn khác sai:</strong> Chạy qua mọi model là tốn kém và không phải routing; điều phối worker là orchestrator–workers; lặp sinh và chấm là evaluator–optimizer."},
  {"level": 1, "q": "Parallelization kiểu sectioning là gì?", "options": ["Chạy cùng một prompt nhiều lần để lấy đa số", "Chạy tuần tự từng phần có gate", "Cho model tự chọn số phần", "Chia nhiệm vụ thành các phần độc lập và chạy song song, mỗi phần một lời gọi"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Sectioning chia theo khía cạnh hoặc theo phần dữ liệu đã biết trước, như review bảo mật, hiệu năng, style song song.<br><strong>Vì sao các lựa chọn khác sai:</strong> Chạy cùng prompt nhiều lần là voting; tuần tự có gate là chaining; model tự chọn cách chia là orchestrator–workers."},
  {"level": 1, "q": "Parallelization kiểu voting là gì?", "options": ["Cho người dùng bình chọn câu trả lời", "Chạy cùng một nhiệm vụ nhiều lần (có thể với prompt khác nhau) rồi tổng hợp bằng bỏ phiếu hoặc ngưỡng", "Chia nhiệm vụ thành các phần khác nhau", "Chọn model theo lá phiếu của đội"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Voting tăng độ tin cậy cho quyết định khó, ví dụ đánh giá code có lỗ hổng hay không, đổi lại chi phí nhân lên theo số lần chạy.<br><strong>Vì sao các lựa chọn khác sai:</strong> Bình chọn của người dùng không phải mẫu workflow; chia thành phần khác nhau là sectioning; chọn model không liên quan tới voting."},
  {"level": 1, "q": "Orchestrator–workers là mẫu như thế nào?", "options": ["Code định sẵn 3 nhánh cố định chạy song song", "Một LLM điều phối phân tích nhiệm vụ, quyết định động các việc con, giao cho worker rồi tổng hợp kết quả", "Một LLM sinh, một LLM chấm, lặp lại", "Một prompt duy nhất trả lời mọi thứ"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Điểm đặc trưng là việc chia nhỏ không biết trước; orchestrator quyết định dựa trên input, như sửa code ở nhiều file chưa biết trước.<br><strong>Vì sao các lựa chọn khác sai:</strong> Nhánh cố định do code định sẵn là parallelization; sinh và chấm là evaluator–optimizer; một prompt duy nhất là single call."},
  {"level": 1, "q": "Evaluator–optimizer là mẫu như thế nào?", "options": ["Một LLM phân loại input rồi chuyển tiếp", "Chạy song song rồi bỏ phiếu", "Tối ưu tham số <code>temperature</code> tự động", "Một LLM tạo kết quả, một LLM khác (hoặc cùng model với prompt khác) chấm theo tiêu chí và phản hồi, lặp lại tới khi đạt"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Mẫu này hợp khi có tiêu chí chấm rõ ràng và phản hồi thật sự giúp cải thiện, như dịch văn học hay viết theo rubric.<br><strong>Vì sao các lựa chọn khác sai:</strong> Phân loại rồi chuyển tiếp là routing; song song rồi bỏ phiếu là voting; tối ưu tham số không phải mẫu workflow."},
  {"level": 1, "q": "Khác biệt giữa parallelization và orchestrator–workers là gì?", "options": ["Parallelization: các nhánh do code định sẵn; orchestrator–workers: model quyết định chia thành những việc gì", "Orchestrator–workers không thể chạy song song", "Parallelization luôn chỉ có một request", "Hai mẫu giống hệt nhau"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Câu hỏi then chốt: có biết trước cách chia việc không? Biết trước thì code chia; không biết trước thì cần LLM điều phối.<br><strong>Vì sao các lựa chọn khác sai:</strong> Worker hoàn toàn có thể chạy song song; parallelization gồm nhiều request; hai mẫu khác nhau ở chỗ ai quyết định cách chia."},
  {"level": 1, "q": "Bốn câu hỏi cần kiểm tra trước khi xây agent là gì?", "options": ["Ngôn ngữ lập trình, framework, cloud, database", "Tốc độ, màu giao diện, số người dùng, giá model", "Độ phức tạp, giá trị, khả thi, và lỗi có phát hiện và sửa được không", "Số tool, số token, số model, số lượt"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Nhiệm vụ phải đủ phức tạp, đáng chi phí, Claude làm tốt được, và lỗi phải bắt được qua test, review hoặc rollback.<br><strong>Vì sao các lựa chọn khác sai:</strong> Các bộ còn lại là chi tiết kỹ thuật hoặc không liên quan tới việc có nên để model tự điều khiển hay không."},
  {"level": 1, "q": "Khi trả lời 4 câu hỏi kiểm tra agent mà có một câu trả lời \"không\", nên làm gì?", "options": ["Vẫn xây agent nhưng dùng model mạnh hơn", "Ở lại tầng đơn giản hơn (workflow hoặc single call) hoặc thêm kiểm soát như cổng phê duyệt của con người", "Tăng effort lên max", "Xây multi-agent để bù"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Một câu \"không\" là đủ để giảm mức tự động; đặc biệt khi lỗi khó phát hiện hoặc không đảo ngược được.<br><strong>Vì sao các lựa chọn khác sai:</strong> Model mạnh hơn hay effort cao hơn không giải quyết được vấn đề cấu trúc; multi-agent còn làm tăng rủi ro và chi phí."},
  {"level": 1, "q": "Multi-agent đáng chi phí khi nào?", "options": ["Với mọi câu hỏi để trả lời nhanh hơn", "Khi nhiệm vụ chỉ cần trích xuất vài trường", "Khi không có tool nào", "Khi công việc chia nhánh được hoặc một agent sẽ tràn context vì phải đọc quá nhiều"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Multi-agent đổi rất nhiều token lấy khả năng song song và cô lập context; chỉ đáng khi bài toán cần đúng những điều đó.<br><strong>Vì sao các lựa chọn khác sai:</strong> Câu hỏi đơn giản nên dùng một lần gọi; trích xuất vài trường là single call; không có tool thì không có việc để giao cho worker."},
  {"level": 1, "q": "Nhược điểm lớn nhất của multi-agent so với một agent là gì?", "options": ["Tốn nhiều token hơn nhiều lần và điều phối phức tạp hơn", "Không dùng được với TypeScript", "Không chạy được trên AWS", "Không hỗ trợ tool"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Mỗi subagent có context riêng, phải đọc lại nhiều thứ, cộng thêm chi phí điều phối và tổng hợp.<br><strong>Vì sao các lựa chọn khác sai:</strong> Multi-agent xây được bằng mọi ngôn ngữ, chạy được trên AWS và các agent đều dùng tool."},
  {"level": 1, "q": "Worker trong mẫu orchestrator–workers làm việc đơn giản (trích xuất, tóm tắt ngắn) nên dùng model nào?", "options": ["Bắt buộc dùng cùng model với orchestrator", "Luôn dùng model đắt nhất", "Không được dùng model của Anthropic", "Có thể dùng model rẻ và nhanh hơn như Haiku hoặc Sonnet"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Chọn model theo độ khó của việc con giúp giảm chi phí mà không giảm chất lượng tổng thể.<br><strong>Vì sao các lựa chọn khác sai:</strong> Không có ràng buộc cùng model; model đắt nhất lãng phí với việc đơn giản; worker dùng Claude là bình thường."},
  {"level": 1, "q": "Vì sao nên giữ vòng lặp chính của agent trên một model duy nhất?", "options": ["Vì API cấm đổi model", "Vì model khác không hiểu tiếng Việt", "Vì đổi model làm mất tool", "Cache được tách theo model; đổi model giữa chừng làm mất cache của toàn bộ lịch sử"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Giữ một model cho vòng chính và giao việc rẻ cho subagent giúp giữ cache và giảm chi phí.<br><strong>Vì sao các lựa chọn khác sai:</strong> API cho phép đổi model mỗi request; các model đều hiểu tiếng Việt; tools vẫn được gửi kèm request, chỉ cache bị mất."},
  {"level": 1, "q": "Bước phân loại (router) trong routing thường nên dùng model nào?", "options": ["Model mạnh nhất để chắc chắn", "Model nhanh, rẻ như <code>claude-haiku-4-5</code>, kèm structured output", "Không cần model, luôn dùng regex", "Model sinh ảnh"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Phân loại vào vài nhóm là việc đơn giản; model nhanh giữ độ trễ và chi phí thấp cho mọi request.<br><strong>Vì sao các lựa chọn khác sai:</strong> Model mạnh nhất cho bước phân loại làm tăng chi phí mỗi request; regex đôi khi đủ nhưng không phải lúc nào cũng hiểu được ngôn ngữ tự nhiên; model sinh ảnh không liên quan."},
  {"level": 1, "q": "Vì sao router nên dùng structured output với <code>enum</code> cho nhãn phân loại?", "options": ["Kết quả luôn đúng schema, parse được ngay và chỉ nhận các nhãn hợp lệ", "Structured output làm model trả lời nhanh gấp đôi", "Structured output là bắt buộc với Haiku", "Để model giải thích dài hơn"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Schema với <code>enum</code> loại bỏ câu trả lời tự do khó parse, giúp code rẽ nhánh an toàn.<br><strong>Vì sao các lựa chọn khác sai:</strong> Structured output không nhằm tăng tốc; không bắt buộc với model nào; mục đích là ràng buộc định dạng chứ không phải kéo dài câu trả lời."},
  {"level": 1, "q": "Điều kiện tiên quyết để evaluator–optimizer hiệu quả là gì?", "options": ["Có tiêu chí chấm rõ ràng và phản hồi thật sự giúp cải thiện kết quả", "Có ít nhất 10 model khác nhau", "Không giới hạn số vòng lặp", "Người dùng cuối tự chấm mỗi vòng"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Rubric rõ ràng làm điểm ổn định; phản hồi cụ thể giúp bản sau tốt hơn bản trước.<br><strong>Vì sao các lựa chọn khác sai:</strong> Không cần nhiều model; vòng lặp phải có giới hạn; người dùng cuối chấm từng vòng thì không còn tự động."},
  {"level": 1, "q": "Vòng lặp evaluator–optimizer bắt buộc phải có gì?", "options": ["Tăng <code>max_tokens</code> mỗi vòng", "Đổi model mỗi vòng", "Giới hạn số vòng tối đa và giữ lại bản tốt nhất", "Xoá phản hồi của vòng trước"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Không giới hạn thì chi phí và độ trễ không kiểm soát được; điểm có thể dao động nên cần giữ bản điểm cao nhất.<br><strong>Vì sao các lựa chọn khác sai:</strong> Tăng <code>max_tokens</code> hay đổi model không kiểm soát được vòng lặp; xoá phản hồi làm bản sau không cải thiện."},
  {"level": 1, "q": "Trong vòng lặp agent tự viết, <code>stop_reason</code> bằng <code>\"tool_use\"</code> có nghĩa là gì?", "options": ["Model đã trả lời xong", "Request bị lỗi do tool", "Model muốn gọi tool; code phải chạy tool và gửi lại <code>tool_result</code>", "Model hết <code>max_tokens</code>"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Đây là tín hiệu để vòng lặp tiếp tục: thực thi tool rồi gửi kết quả trong lượt user tiếp theo.<br><strong>Vì sao các lựa chọn khác sai:</strong> Trả lời xong là <code>end_turn</code>; lỗi tool được báo trong <code>tool_result</code> với <code>is_error</code>; hết token là <code>max_tokens</code>."},
  {"level": 1, "q": "Khi gửi kết quả tool trở lại, block <code>tool_result</code> phải chứa trường nào để liên kết với lời gọi?", "options": ["<code>tool_name</code> là đủ", "<code>tool_use_id</code> trùng với <code>id</code> của block <code>tool_use</code> tương ứng", "<code>request_id</code> của HTTP", "Không cần liên kết"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> <code>tool_use_id</code> giúp model biết kết quả nào thuộc lời gọi nào, nhất là khi gọi nhiều tool song song.<br><strong>Vì sao các lựa chọn khác sai:</strong> Tên tool không phân biệt được hai lời gọi cùng tool; request id HTTP không liên quan; thiếu liên kết thì API từ chối."},
  {"level": 1, "q": "Trong vòng lặp agent, các block <code>tool_result</code> được gửi lại cho model trong message có role nào?", "options": ["<code>user</code>", "<code>assistant</code>", "<code>system</code>", "<code>tool</code>"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Kết quả tool được gửi trong lượt user ngay sau lượt assistant chứa các block <code>tool_use</code> tương ứng.<br><strong>Vì sao các lựa chọn khác sai:</strong> Lượt assistant chứa lời gọi tool chứ không chứa kết quả; <code>system</code> dùng cho chỉ dẫn của operator; Messages API không có role <code>tool</code>."},
  {"level": 1, "q": "Trước khi quyết định chuyển từ single call sang workflow hay agent, nên làm gì?", "options": ["Hỏi ý kiến một người dùng", "Chọn theo bài blog mới nhất", "Chạy eval trên bộ dữ liệu có đáp án để so sánh chất lượng, chi phí và độ trễ", "Chuyển ngay vì agent luôn tốt hơn"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Quyết định dựa trên số liệu giúp chọn kiến trúc đơn giản nhất đạt mục tiêu.<br><strong>Vì sao các lựa chọn khác sai:</strong> Một ý kiến đơn lẻ không đại diện; bài blog không biết dữ liệu của bạn; agent không phải lúc nào cũng tốt hơn."},
  {"level": 1, "q": "Khi giao việc cho subagent, mô tả nhiệm vụ cần có những gì?", "options": ["Chỉ một câu \"làm phần của bạn\"", "Toàn bộ lịch sử hội thoại của agent chính", "Không cần mô tả, subagent tự hiểu", "Mục tiêu rõ ràng, định dạng kết quả trả về và giới hạn phạm vi"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Subagent không thấy context của agent chính; mô tả rõ giúp tránh làm trùng, làm thiếu hoặc lạc đề.<br><strong>Vì sao các lựa chọn khác sai:</strong> Câu mơ hồ dẫn tới worker làm trùng việc; gửi toàn bộ lịch sử làm mất lợi ích cô lập context; subagent không thể tự đoán ý định."},
  {"level": 1, "q": "Agent có tool <code>refundOrder</code> (hoàn tiền không đảo ngược được). Biện pháp kiểm soát phù hợp nhất?", "options": ["Cho agent tự quyết để nhanh hơn", "Dùng model rẻ hơn cho bước hoàn tiền", "Bắt buộc con người phê duyệt trước khi thực thi hoàn tiền", "Tăng <code>max_tokens</code>"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Hành động không đảo ngược có chi phí sai cao; cổng phê duyệt giữ lợi ích tự động hoá mà vẫn kiểm soát rủi ro.<br><strong>Vì sao các lựa chọn khác sai:</strong> Tự quyết hoàn toàn rủi ro cao; model rẻ hơn không giảm rủi ro; <code>max_tokens</code> không liên quan."},
  {"level": 1, "q": "Với agent sửa code, tín hiệu phản hồi đáng tin nhất từ môi trường là gì?", "options": ["Model tự nói \"tôi đã sửa xong\"", "Số dòng code thay đổi", "Kết quả chạy test, type check và build", "Độ dài câu trả lời"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Agent cần sự thật từ môi trường ở mỗi bước; test và compiler cho phản hồi khách quan để agent tự sửa.<br><strong>Vì sao các lựa chọn khác sai:</strong> Lời tự khẳng định của model không phải kiểm chứng; số dòng hay độ dài không nói lên tính đúng đắn."},
  {"level": 1, "q": "Trong vòng lặp agent, giá trị <code>stop_reason</code> nào cho biết model đã hoàn tất lượt và vòng lặp có thể dừng?", "options": ["<code>tool_use</code>", "<code>end_turn</code>", "<code>max_tokens</code>", "<code>pause_turn</code>"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> <code>end_turn</code> nghĩa là model kết thúc câu trả lời một cách tự nhiên, không yêu cầu gọi thêm tool.<br><strong>Vì sao các lựa chọn khác sai:</strong> <code>tool_use</code> báo model cần chạy tool rồi tiếp tục; <code>max_tokens</code> là bị cắt do hết giới hạn output; <code>pause_turn</code> là lượt tạm dừng cần gửi lại để tiếp tục."},
  {"level": 2, "q": "Router trong NestJS dưới đây đôi khi làm cả request lỗi 500. Cải tiến nào hợp lý nhất?<pre><code>// apps/api/src/support/router.service.ts\nasync route(q: string): Promise&lt;\"simple\" | \"complex\"&gt; {\n  const r = await this.client.messages.create({\n    model: \"claude-haiku-4-5\",\n    max_tokens: 100,\n    output_config: { format: { type: \"json_schema\", schema: ROUTER_SCHEMA } },\n    messages: [{ role: \"user\", content: `Phân loại độ khó:\\n&lt;q&gt;${q}&lt;/q&gt;` }],\n  });\n  const block = r.content[0] as Anthropic.TextBlock;\n  return JSON.parse(block.text).difficulty;\n}</code></pre>", "options": ["Bắt lỗi parse hoặc nhãn lạ và mặc định đi nhánh an toàn (<code>complex</code>), đồng thời log lại để theo dõi", "Bỏ structured output để model trả lời tự do", "Tăng <code>max_tokens</code> của router lên 16.000", "Gọi router 5 lần cho chắc"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Bước phân loại có thể thất bại (lỗi mạng, refusal, text rỗng); fallback về nhánh mạnh hơn giữ trải nghiệm đúng, log giúp phát hiện tỉ lệ lỗi.<br><strong>Vì sao các lựa chọn khác sai:</strong> Bỏ structured output làm parse khó hơn; <code>max_tokens</code> lớn không cần cho một nhãn; gọi 5 lần nhân chi phí mà không xử lý được lỗi."},
  {"level": 2, "q": "Bước chaining viết dàn ý rồi viết bài. Cổng kiểm tra nào dưới đây đúng tinh thần prompt chaining?<pre><code>const outline = await ask(`Viết dàn ý 5 mục cho bài về: ${topic}. Mỗi mục 1 dòng.`);\nconst items = outline.split(\"\\n\").filter((l) =&gt; l.trim());\n// cổng kiểm tra đặt ở đây\nconst article = await ask(`Viết bài 800 từ theo dàn ý:\\n${outline}`);</code></pre>", "options": ["Bỏ qua kiểm tra, cứ viết bài rồi tính sau", "Để model viết bài tự kiểm tra dàn ý của chính nó", "Đếm số mục của dàn ý bằng code; nếu sai thì yêu cầu sửa một lần, vẫn sai thì dừng và báo lỗi", "Lặp vô hạn cho tới khi dàn ý đúng"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Điều kiện đo được (đúng 5 mục) nên kiểm tra bằng code, rẻ và tất định; có giới hạn số lần sửa để không kéo dài vô tận.<br><strong>Vì sao các lựa chọn khác sai:</strong> Bỏ gate để lỗi lan sang bước sau; để bước sau tự kiểm tra thì lỗi đã lan rồi; lặp vô hạn không kiểm soát được chi phí."},
  {"level": 2, "q": "Đoạn code dưới đây dịch mô tả sản phẩm sang 5 ngôn ngữ. Đây là mẫu gì?<pre><code>const LANGS = [\"en\", \"ja\", \"ko\", \"zh\", \"th\"];\nconst translations = await Promise.all(\n  LANGS.map((lang) =&gt; ask(`Dịch sang ${lang}, giữ giọng thương hiệu:\\n${description}`)),\n);</code></pre>", "options": ["Orchestrator–workers", "Voting", "Evaluator–optimizer", "Parallelization kiểu sectioning: các nhánh độc lập do code định sẵn, chạy song song"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Danh sách ngôn ngữ biết trước, mỗi bản dịch độc lập, code quyết định các nhánh.<br><strong>Vì sao các lựa chọn khác sai:</strong> Không có LLM nào quyết định cách chia nên không phải orchestrator; các nhánh làm việc khác nhau nên không phải voting; không có bước chấm và phản hồi."},
  {"level": 2, "q": "Hàm voting dưới đây kiểm tra code có lỗ hổng bằng 3 lời gọi. Lỗi logic là gì?<pre><code>async function vote(code: string, n = 3) {\n  const results = await Promise.all(Array.from({ length: n }, () =&gt; check(code)));\n  const yes = results.filter((r) =&gt; r.vulnerable).length;\n  return { vulnerable: yes &gt;= 1, votes: `${yes}/${n}` };\n}</code></pre>", "options": ["<code>Promise.all</code> không chạy song song", "Phải dùng <code>for</code> tuần tự để đếm phiếu đúng", "Không có lỗi", "Điều kiện <code>yes &gt;= 1</code> biến voting thành \"chỉ cần một phiếu\"; đa số phải là <code>yes * 2 &gt; n</code>"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Voting lấy đa số hoặc ngưỡng đã chọn có chủ đích; một phiếu là đủ thì độ nhạy tăng nhưng mất ý nghĩa đa số (trừ khi đó là chính sách có chủ ý và ghi rõ).<br><strong>Vì sao các lựa chọn khác sai:</strong> <code>Promise.all</code> chạy các promise đồng thời; chạy tuần tự không làm đếm đúng hơn; điều kiện hiện tại sai với mục tiêu lấy đa số."},
  {"level": 2, "q": "Vòng evaluator–optimizer dưới đây chạy tốt trên dev nhưng có ngày tốn hàng trăm đô. Nguyên nhân?<pre><code>let title = await write(topic);\nlet grade = await judge(title);\nwhile (grade.score &lt; 8) {\n  title = await write(topic, grade.feedback);\n  grade = await judge(title);\n}\nreturn title;</code></pre>", "options": ["<code>judge</code> dùng structured output", "Dùng <code>while</code> thay vì <code>for</code>", "Ngưỡng 8 quá thấp", "Không có giới hạn số vòng; nếu điểm không bao giờ đạt 8 thì lặp mãi"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Vòng lặp chỉ dừng khi đạt ngưỡng; rubric khó hoặc đầu vào xấu làm nó chạy vô hạn. Cần <code>maxRounds</code> và giữ bản tốt nhất.<br><strong>Vì sao các lựa chọn khác sai:</strong> Structured output cho judge là đúng; <code>while</code> hay <code>for</code> không phải vấn đề, thiếu điều kiện dừng mới là vấn đề; ngưỡng thấp hơn không gây lặp vô hạn."},
  {"level": 2, "q": "Vòng evaluator–optimizer có giới hạn 3 vòng nhưng người duyệt phàn nàn kết quả đôi khi tệ hơn vòng đầu. Lỗi ở đâu?<pre><code>let feedback: string | undefined;\nlet title = \"\";\nfor (let i = 0; i &lt; 3; i++) {\n  title = await write(topic, feedback);\n  const g = await judge(title);\n  if (g.score &gt;= 8) break;\n  feedback = g.feedback;\n}\nreturn title;</code></pre>", "options": ["Giới hạn 3 vòng là quá ít", "Không được truyền feedback vào vòng sau", "Luôn trả bản của vòng cuối; cần giữ và trả bản có điểm cao nhất", "Nên dùng cùng một prompt cho writer và judge"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Điểm có thể giảm ở vòng sau; lưu bản tốt nhất đảm bảo kết quả không bao giờ kém hơn điều đã đạt.<br><strong>Vì sao các lựa chọn khác sai:</strong> Tăng số vòng không sửa được việc chọn sai bản; truyền feedback là cốt lõi của mẫu; writer và judge cần prompt khác nhau."},
  {"level": 2, "q": "Đoạn code dưới đây thuộc mẫu nào?<pre><code>const plan = await planTasks(issue); // [{ id, goal, files[] }] do model sinh ra\nconst results = await Promise.all(plan.tasks.map((t) =&gt; runWorker(t)));\nconst summary = await synthesize(issue, results);</code></pre>", "options": ["Routing", "Prompt chaining cố định", "Voting", "Orchestrator–workers: model lập kế hoạch chia việc động, code chạy worker cho từng việc rồi tổng hợp"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Số lượng và nội dung subtask do model quyết định dựa trên input; worker thực thi rồi bước tổng hợp gộp lại.<br><strong>Vì sao các lựa chọn khác sai:</strong> Routing chọn một nhánh cho input chứ không chia nhiều việc; chaining cố định có các bước biết trước; voting chạy cùng một việc nhiều lần."},
  {"level": 2, "q": "Vòng lặp agent tự viết dưới đây bị API trả lỗi 400 ở lượt thứ hai. Vì sao?<pre><code>while (true) {\n  const res = await client.messages.create({ model: \"claude-opus-5\", max_tokens: 8000, tools, messages });\n  if (res.stop_reason === \"end_turn\") break;\n  const calls = res.content.filter((b): b is Anthropic.ToolUseBlock =&gt; b.type === \"tool_use\");\n  const results = await Promise.all(calls.map(async (c) =&gt; ({\n    type: \"tool_result\" as const, tool_use_id: c.id, content: await exec(c.name, c.input),\n  })));\n  messages.push({ role: \"user\", content: results });\n}</code></pre>", "options": ["<code>tool_result</code> phải nằm trong lượt assistant", "Không được gọi <code>messages.create</code> hai lần", "Không đưa lượt assistant (chứa block <code>tool_use</code>) vào <code>messages</code> trước khi gửi <code>tool_result</code>", "Phải dùng streaming khi có tool"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Mỗi <code>tool_result</code> phải tham chiếu một <code>tool_use</code> ở lượt assistant ngay trước; thiếu lượt assistant thì API không tìm thấy lời gọi tương ứng.<br><strong>Vì sao các lựa chọn khác sai:</strong> <code>tool_result</code> nằm trong lượt user; gọi API nhiều lần là bản chất của vòng lặp; streaming không bắt buộc khi dùng tool."},
  {"level": 2, "q": "Vòng lặp agent dưới đây đã đúng giao thức nhưng thiếu một biện pháp an toàn quan trọng cho production. Đó là gì?<pre><code>while (true) {\n  const res = await client.messages.create({ model: \"claude-opus-5\", max_tokens: 8000, tools, messages });\n  messages.push({ role: \"assistant\", content: res.content });\n  if (res.stop_reason === \"end_turn\") break;\n  messages.push({ role: \"user\", content: await runTools(res.content) });\n}</code></pre>", "options": ["Thêm <code>console.log</code> cho mỗi lượt", "Giới hạn số lượt (và ngân sách token/thời gian) để agent không chạy mãi", "Đổi <code>while (true)</code> thành đệ quy", "Bỏ kiểm tra <code>end_turn</code>"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Agent có thể lặp gọi tool không hội tụ; giới hạn lượt và ngân sách là chốt chặn chi phí và độ trễ.<br><strong>Vì sao các lựa chọn khác sai:</strong> Log có ích nhưng không ngăn vòng lặp vô hạn; đệ quy không thay đổi bản chất; bỏ kiểm tra <code>end_turn</code> làm vòng lặp không bao giờ dừng đúng."},
  {"level": 2, "q": "Tool <code>queryOrders</code> ném exception khi database timeout. Cách trả kết quả về cho model đúng là gì?<pre><code>try {\n  content = JSON.stringify(await this.orders.find(input));\n} catch (e) {\n  // trả về gì ở đây?\n}</code></pre>", "options": ["Để exception làm sập cả vòng lặp", "Trả <code>tool_result</code> với <code>is_error: true</code> và thông báo lỗi dễ hiểu để model thử cách khác hoặc báo lại", "Trả <code>tool_result</code> rỗng như thành công", "Bỏ qua lời gọi đó, không gửi <code>tool_result</code>"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Báo lỗi rõ ràng giúp model thích nghi (thử lại, dùng tool khác, hỏi người dùng) thay vì suy luận trên dữ liệu rỗng.<br><strong>Vì sao các lựa chọn khác sai:</strong> Sập vòng lặp làm mất công việc đang làm; kết quả rỗng khiến model tưởng không có đơn hàng; thiếu <code>tool_result</code> cho một <code>tool_use</code> là request không hợp lệ."},
  {"level": 2, "q": "Nhiệm vụ: sinh mô tả sản phẩm từ thông số, rồi dịch sang 5 ngôn ngữ. Kiến trúc phù hợp nhất?", "options": ["Agent tự quyết định cần dịch sang ngôn ngữ nào", "Multi-agent 6 agent", "Evaluator–optimizer cho từng từ", "Prompt chaining (viết rồi dịch) kết hợp parallelization cho 5 bản dịch"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Các bước biết trước và các bản dịch độc lập với nhau: chuỗi hai bước, bước sau chạy song song.<br><strong>Vì sao các lựa chọn khác sai:</strong> Ngôn ngữ đã biết trước nên không cần agent; multi-agent quá tốn kém; chấm từng từ là thừa và chậm."},
  {"level": 2, "q": "Chatbot hỗ trợ nhận câu hỏi thuộc 3 nhóm rõ ràng: billing, kỹ thuật, chung; mỗi nhóm cần tài liệu và quy trình khác nhau. Mẫu phù hợp?", "options": ["Voting", "Orchestrator–workers", "Evaluator–optimizer", "Routing"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Input chia thành nhóm rõ ràng và mỗi nhóm có xử lý riêng là dấu hiệu điển hình của routing.<br><strong>Vì sao các lựa chọn khác sai:</strong> Voting dùng để tăng độ tin cậy một quyết định; orchestrator dùng khi phải chia việc động; evaluator dùng khi có rubric để lặp cải thiện."},
  {"level": 2, "q": "Nhiệm vụ: tự sửa một bug mô tả trong issue GitHub, không biết trước phải đọc và sửa những file nào, repo có bộ test đầy đủ. Kiến trúc phù hợp?", "options": ["Một lần gọi API với toàn bộ issue", "Routing theo nhãn issue", "Chaining 3 bước cố định", "Agent có tool đọc, sửa file và chạy test"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Các bước không biết trước và có test để kiểm chứng: đủ điều kiện để model tự điều khiển vòng lặp.<br><strong>Vì sao các lựa chọn khác sai:</strong> Một lần gọi không đọc được code cần thiết; routing chỉ phân loại; chuỗi cố định không thích ứng được với nơi bug thực sự nằm."},
  {"level": 2, "q": "Team marketing cần slogan đạt rubric nội bộ 8/10 (rõ ràng, đúng giọng thương hiệu, tối đa 8 từ). Mẫu phù hợp?", "options": ["Routing", "Evaluator–optimizer", "Voting", "Multi-agent nghiên cứu"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Có tiêu chí chấm rõ và có thể cải thiện qua phản hồi: đúng điều kiện của evaluator–optimizer.<br><strong>Vì sao các lựa chọn khác sai:</strong> Không có nhóm input cần rẽ nhánh; voting chọn đa số chứ không cải thiện bản viết; nghiên cứu nhiều nguồn không phải bài toán ở đây."},
  {"level": 2, "q": "GitHub Actions cần review một PR theo 3 khía cạnh độc lập: bảo mật, hiệu năng, quy ước code. Đoạn nào triển khai đúng mẫu sectioning?<pre><code>const ASPECTS = {\n  security: \"Tìm lỗ hổng: injection, lộ secret, thiếu kiểm tra quyền.\",\n  performance: \"Tìm N+1 query Prisma, vòng lặp tốn kém, thiếu index.\",\n  conventions: \"Kiểm tra quy ước đặt tên, cấu trúc module NestJS.\",\n};\nconst reviews = await Promise.all(\n  Object.entries(ASPECTS).map(([k, focus]) =&gt; reviewDiff(diff, focus).then((r) =&gt; [k, r])),\n);</code></pre>", "options": ["Chạy 3 lời gọi song song, mỗi lời gọi một prompt chuyên cho một khía cạnh, rồi gộp kết quả", "Một prompt yêu cầu review mọi khía cạnh cùng lúc", "Chạy cùng một prompt 3 lần rồi bỏ phiếu", "Để agent tự quyết có review bảo mật hay không"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Mỗi prompt tập trung vào một khía cạnh cho kết quả sâu hơn; các nhánh độc lập nên chạy song song được.<br><strong>Vì sao các lựa chọn khác sai:</strong> Một prompt gộp dễ bỏ sót khía cạnh; chạy cùng prompt 3 lần là voting; bỏ quyết định bảo mật cho agent là rủi ro."},
  {"level": 2, "q": "Nhiệm vụ: viết release note từ danh sách commit của một tag (đọc commit, nhóm theo loại, viết văn bản). Kiến trúc phù hợp?", "options": ["Agent tự khám phá repo", "Multi-agent mỗi agent một commit", "Một lần gọi API (hoặc workflow ngắn) với danh sách commit", "Voting 5 lần"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Đầu vào có sẵn, các bước biết trước, không cần tool: một lần gọi là đủ.<br><strong>Vì sao các lựa chọn khác sai:</strong> Agent và multi-agent thêm chi phí không cần thiết; voting không cải thiện một văn bản tổng hợp."},
  {"level": 2, "q": "Refactor đổi tên một API dùng chung trong <code>packages/shared</code>, chưa biết bao nhiêu nơi trong <code>apps/*</code> bị ảnh hưởng, mỗi nơi cần sửa khác nhau. Mẫu phù hợp?", "options": ["Parallelization với 3 nhánh cố định", "Routing theo tên file", "Orchestrator–workers: orchestrator tìm nơi bị ảnh hưởng, chia việc cho worker, rồi tổng hợp và chạy test", "Một lần gọi API"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Số việc con và nội dung từng việc chỉ biết sau khi phân tích input, đúng trường hợp của orchestrator–workers.<br><strong>Vì sao các lựa chọn khác sai:</strong> Nhánh cố định không phản ánh số nơi thực tế; routing không chia nhiều việc; một lần gọi không đủ để sửa nhiều module."},
  {"level": 2, "q": "Route handler Next.js định tuyến câu hỏi. Vì sao mỗi nhánh nên có system prompt cố định riêng và dùng một model cố định?<pre><code>// apps/web/app/api/support/route.ts\nconst ROUTES = {\n  simple: { model: \"claude-haiku-4-5\", system: [{ type: \"text\", text: FAQ, cache_control: { type: \"ephemeral\" } }] },\n  complex: { model: \"claude-opus-5\", system: [{ type: \"text\", text: POLICY, cache_control: { type: \"ephemeral\" } }] },\n} as const;\nconst route = ROUTES[await classify(question)];</code></pre>", "options": ["Vì Next.js không cho dùng chung biến", "Vì Haiku không đọc được system prompt dài", "Mỗi nhánh có prefix ổn định nên được cache hiệu quả, và hành vi của từng nhánh dễ đo lường", "Vì routing bắt buộc phải có 2 API key"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Nhánh FAQ trên Haiku với FAQ được cache và nhánh phức tạp trên Opus với prompt riêng: mỗi nhánh giữ cache riêng theo model và prompt.<br><strong>Vì sao các lựa chọn khác sai:</strong> Next.js không có giới hạn như vậy; Haiku đọc được system prompt dài; routing không yêu cầu nhiều API key."},
  {"level": 2, "q": "Workflow GitHub Actions dưới đây review từng package bị ảnh hưởng. Nó hiện thực mẫu nào?<pre><code>jobs:\n  affected:\n    runs-on: ubuntu-latest\n    outputs:\n      packages: ${{ steps.list.outputs.packages }}\n    steps:\n      - uses: actions/checkout@v4\n        with: { fetch-depth: 0 }\n      - id: list # định dạng JSON của turbo ls có thể khác theo phiên bản, kiểm tra tài liệu\n        run: echo \"packages=$(npx turbo ls --affected --output=json | jq -c '[.packages.items[].name]')\" &gt;&gt; \"$GITHUB_OUTPUT\"\n  review:\n    needs: affected\n    strategy:\n      matrix:\n        pkg: ${{ fromJson(needs.affected.outputs.packages) }}\n    runs-on: ubuntu-latest\n    steps:\n      - run: echo \"review ${{ matrix.pkg }}\"</code></pre>", "options": ["Orchestrator–workers do LLM quyết định", "Evaluator–optimizer", "Parallelization: danh sách nhánh do code (Turborepo) tính ra, mỗi package một job chạy song song", "Voting"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Package bị ảnh hưởng được tính tất định từ dependency graph; không có LLM nào quyết định cách chia.<br><strong>Vì sao các lựa chọn khác sai:</strong> Không có LLM điều phối; không có vòng chấm và sửa; mỗi job làm việc khác nhau chứ không bỏ phiếu cho cùng một việc."},
  {"level": 2, "q": "Schema dưới đây dùng cho router. Thay đổi nào giúp kết quả parse chắc chắn có nhãn hợp lệ?<pre><code>const ROUTER_SCHEMA = {\n  type: \"object\",\n  properties: {\n    category: { type: \"string\", enum: [\"billing\", \"technical\", \"general\"] },\n  },\n};</code></pre>", "options": ["Đổi <code>enum</code> thành <code>type: \"string\"</code> tự do", "Xoá <code>properties</code>", "Thêm <code>required: [\"category\"]</code> và <code>additionalProperties: false</code>", "Thêm <code>temperature</code> vào schema"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Không có <code>required</code> thì object rỗng vẫn hợp lệ; <code>additionalProperties: false</code> chặn trường lạ, giúp code rẽ nhánh an toàn.<br><strong>Vì sao các lựa chọn khác sai:</strong> Bỏ <code>enum</code> cho phép nhãn tuỳ ý; xoá <code>properties</code> làm schema vô nghĩa; <code>temperature</code> không thuộc JSON schema."},
  {"level": 2, "q": "Cổng kiểm tra cần xác nhận: output là JSON hợp lệ, có đủ trường <code>price</code> và <code>cta</code>, độ dài không quá 120 từ. Nên hiện thực bằng gì?", "options": ["Bằng một lời gọi LLM khác để chấm", "Bằng voting 3 lần", "Không cần kiểm tra vì structured output lo hết", "Bằng code (parse JSON, kiểm tra trường, đếm từ), vì tiêu chí đo được một cách tất định"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Tiêu chí đo được bằng code thì kiểm tra bằng code: rẻ, nhanh, không sai lệch. LLM chỉ nên chấm những tiêu chí cần phán đoán như giọng văn.<br><strong>Vì sao các lựa chọn khác sai:</strong> Dùng LLM cho việc code làm được là tốn và kém ổn định; voting nhân chi phí vô ích; structured output bảo đảm schema nhưng không kiểm tra số từ hay logic nghiệp vụ."},
  {"level": 2, "q": "Router trả về cả nhãn và mức tự tin. Chuyển nhầm câu phức tạp sang Haiku gây hậu quả lớn hơn chiều ngược lại. Logic nào hợp lý?<pre><code>type Route = { category: \"simple\" | \"complex\"; confidence: \"low\" | \"medium\" | \"high\" };\nfunction pick(r: Route): \"simple\" | \"complex\" {\n  // viết điều kiện ở đây\n}</code></pre>", "options": ["Luôn đi nhánh <code>simple</code> để tiết kiệm", "Chọn ngẫu nhiên khi tự tin thấp", "Bỏ qua mức tự tin, chỉ dùng nhãn", "Chỉ đi nhánh <code>simple</code> khi nhãn là <code>simple</code> và mức tự tin cao; còn lại đi <code>complex</code>"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Khi chi phí sai lệch bất đối xứng, nghiêng về nhánh an toàn lúc không chắc chắn; ngưỡng tự tin nên được hiệu chỉnh bằng eval.<br><strong>Vì sao các lựa chọn khác sai:</strong> Luôn đi nhánh rẻ bỏ qua rủi ro; chọn ngẫu nhiên không có cơ sở; bỏ mức tự tin là bỏ thông tin hữu ích để quản lý rủi ro."},
  {"level": 2, "q": "Khi nào parallelization kiểu voting đáng chi phí?", "options": ["Mọi request để chắc chắn", "Trả lời câu hỏi FAQ đơn giản", "Quyết định có rủi ro cao hoặc khó (ví dụ gắn cờ lỗ hổng bảo mật), nơi độ tin cậy quan trọng hơn chi phí gấp n lần", "Sinh tiêu đề blog ngắn"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Voting giảm dao động của một lần gọi và cho thấy mức đồng thuận, đáng giá khi sai lầm đắt.<br><strong>Vì sao các lựa chọn khác sai:</strong> Áp dụng cho mọi request nhân chi phí vô ích; FAQ và tiêu đề ngắn là việc rủi ro thấp, một lần gọi là đủ."},
  {"level": 2, "q": "Vòng evaluator–optimizer dưới đây có điểm không cải thiện qua các vòng. Nguyên nhân có khả năng nhất?<pre><code>let best = { score: -1, text: \"\" };\nfor (let i = 0; i &lt; 3; i++) {\n  const text = await write(topic);            // luôn gọi như nhau\n  const { score, feedback } = await judge(text);\n  if (score &gt; best.score) best = { score, text };\n  if (score &gt;= 8) break;\n}</code></pre>", "options": ["Feedback của judge không được truyền vào lần viết tiếp theo", "Judge dùng structured output", "Giới hạn 3 vòng", "Writer dùng <code>claude-opus-5</code>"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Không có feedback thì writer chỉ sinh lại ngẫu nhiên; cốt lõi của mẫu là phản hồi cụ thể được đưa vào vòng sau.<br><strong>Vì sao các lựa chọn khác sai:</strong> Structured output cho judge là đúng cách; giới hạn vòng là cần thiết; model mạnh không phải nguyên nhân khiến không cải thiện."},
  {"level": 2, "q": "Orchestrator giao việc cho 4 worker bằng câu \"Hãy xử lý phần việc của bạn trong refactor này\". Kết quả: worker sửa trùng file và bỏ sót module. Cách sửa đúng?", "options": ["Tăng số worker lên 10", "Mô tả rõ cho từng worker: mục tiêu, danh sách file thuộc phạm vi, định dạng kết quả, và những gì không được đụng tới", "Dùng model mạnh hơn cho worker", "Bỏ bước tổng hợp"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Worker không thấy context của orchestrator; phạm vi và đầu ra rõ ràng tránh chồng chéo và bỏ sót.<br><strong>Vì sao các lựa chọn khác sai:</strong> Thêm worker làm trùng lặp nhiều hơn; model mạnh không đoán được phạm vi chưa được giao; bỏ tổng hợp làm mất bước phát hiện xung đột."},
  {"level": 2, "q": "Orchestrator sinh ra 40 việc con; gọi <code>Promise.all</code> cho cả 40 làm dính rate limit 429. Cách xử lý hợp lý?<pre><code>async function runInBatches&lt;T, R&gt;(items: T[], size: number, fn: (t: T) =&gt; Promise&lt;R&gt;) {\n  const out: R[] = [];\n  for (let i = 0; i &lt; items.length; i += size) {\n    out.push(...(await Promise.all(items.slice(i, i + size).map(fn))));\n  }\n  return out;\n}\nconst results = await runInBatches(plan.tasks, 5, runWorker);</code></pre>", "options": ["Tạo 40 API key để chia tải", "Bỏ qua các việc bị lỗi", "Giới hạn số lời gọi đồng thời (chạy theo lô, ví dụ 5 việc một lúc) và retry có backoff khi gặp 429", "Chuyển tất cả sang chạy tuần tự từng cái một mãi mãi"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Giới hạn đồng thời giữ thông lượng trong hạn mức; SDK cũng có retry cho lỗi tạm thời nhưng không thay thế được việc điều tiết.<br><strong>Vì sao các lựa chọn khác sai:</strong> Lách hạn mức bằng nhiều key là sai cách; bỏ việc lỗi làm kết quả thiếu; tuần tự hoàn toàn đánh mất lợi ích song song."},
  {"level": 2, "q": "3 nhánh review song song độc lập; một nhánh lỗi mạng không nên làm mất kết quả của 2 nhánh còn lại. Đoạn nào phù hợp?<pre><code>const settled = await Promise.allSettled(ASPECTS.map((a) =&gt; reviewDiff(diff, a)));\nconst ok = settled.flatMap((s) =&gt; (s.status === \"fulfilled\" ? [s.value] : []));\nconst failed = settled.filter((s) =&gt; s.status === \"rejected\").length;</code></pre>", "options": ["Dùng <code>Promise.allSettled</code> và xử lý riêng nhánh <code>rejected</code> (retry hoặc đánh dấu thiếu)", "Dùng <code>Promise.all</code> như cũ", "Dùng <code>Promise.race</code> để lấy nhánh nhanh nhất", "Chạy lại cả 3 nhánh khi có một nhánh lỗi"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> <code>allSettled</code> trả về trạng thái từng nhánh, giữ được kết quả thành công và cho phép xử lý lỗi cục bộ.<br><strong>Vì sao các lựa chọn khác sai:</strong> <code>Promise.all</code> reject ngay khi một nhánh lỗi; <code>race</code> chỉ lấy một kết quả; chạy lại cả 3 lãng phí chi phí đã bỏ ra."},
  {"level": 2, "q": "Agent chạy trong job nền cần ngân sách token tối đa 200.000 cho mỗi nhiệm vụ. Cách hiện thực hợp lý?<pre><code>let spent = 0;\nfor (let turn = 0; turn &lt; 30; turn++) {\n  const res = await client.messages.create({ model: \"claude-opus-5\", max_tokens: 8000, tools, messages });\n  const u = res.usage;\n  spent += u.input_tokens + (u.cache_read_input_tokens ?? 0) + (u.cache_creation_input_tokens ?? 0) + u.output_tokens;\n  if (spent &gt; 200_000) throw new BudgetExceeded(spent);\n  // ...\n}</code></pre>", "options": ["Cộng dồn <code>usage</code> sau mỗi lượt và dừng (hoặc chuyển cho người) khi vượt ngân sách", "Đặt <code>max_tokens: 200000</code> cho một request", "Tin rằng agent sẽ tự dừng đúng lúc", "Chỉ đếm số lượt"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> <code>max_tokens</code> chỉ giới hạn output của một request; ngân sách của cả nhiệm vụ phải được code theo dõi qua các lượt.<br><strong>Vì sao các lựa chọn khác sai:</strong> Một request không đại diện cho cả vòng lặp; agent không biết ngân sách của bạn; đếm lượt không phản ánh chi phí thực."},
  {"level": 2, "q": "Vì sao workflow thường dễ debug hơn agent trong production?", "options": ["Đường đi của workflow được code định sẵn, nên log từng bước cho biết chính xác bước nào sai", "Workflow không bao giờ lỗi", "Agent không ghi log được", "Workflow không gọi LLM"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Luồng tất định giúp tái hiện lỗi và đo từng bước; agent có thể đi đường khác mỗi lần chạy.<br><strong>Vì sao các lựa chọn khác sai:</strong> Workflow vẫn có lỗi; agent vẫn log được nhưng đường đi thay đổi; workflow vẫn gọi LLM ở từng bước."},
  {"level": 2, "q": "Agent hỗ trợ có các tool như dưới và thường gọi nhầm tool. Cải tiến nào đúng nhất?<pre><code>const tools = [\n  { name: \"getOrder\", description: \"Lấy đơn\", input_schema: ORDER_ID },\n  { name: \"findOrder\", description: \"Tìm đơn\", input_schema: ORDER_ID },\n  { name: \"orderLookup\", description: \"Tra đơn hàng\", input_schema: ORDER_ID },\n];</code></pre>", "options": ["Thêm nhiều tool hơn cho model lựa chọn", "Đặt tên tool ngắn hơn nữa", "Gộp các tool chồng chéo và viết description rõ khi nào dùng, tham số nghĩa là gì", "Bỏ description để tiết kiệm token"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Ba tool gần như trùng chức năng với mô tả mơ hồ làm model khó chọn; ít tool, mô tả rõ ràng giúp chọn đúng.<br><strong>Vì sao các lựa chọn khác sai:</strong> Thêm tool càng tăng nhầm lẫn; tên ngắn hơn không giúp phân biệt; bỏ description làm model đoán mò."},
  {"level": 2, "q": "Workflow 4 bước chạy trên Lambda, mỗi bước gọi Claude mất tới 3 phút; tổng có lúc vượt giới hạn 15 phút của Lambda. Thiết kế lại thế nào?", "options": ["Tăng timeout Lambda lên 60 phút", "Gộp 4 bước thành một prompt lớn", "Chạy 4 bước song song dù bước sau cần kết quả bước trước", "Tách mỗi bước thành một Lambda riêng, chuyển trạng thái giữa các bước qua SQS (hoặc Step Functions) và lưu kết quả trung gian"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Mỗi bước ngắn gọn trong giới hạn, có thể retry riêng, lưu trạng thái để tiếp tục khi lỗi.<br><strong>Vì sao các lựa chọn khác sai:</strong> Lambda không cho timeout vượt 15 phút; gộp prompt làm mất lợi ích của chaining; bước phụ thuộc nhau không thể song song."},
  {"level": 2, "q": "So sánh cấu hình single call với workflow routing trên bộ eval 300 câu có đáp án. Bộ chỉ số nào nên đo?", "options": ["Tỉ lệ đúng, chi phí trung bình mỗi câu và độ trễ (ví dụ p95)", "Chỉ số token output", "Chỉ độ dài câu trả lời", "Số lượng model được dùng"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Kiến trúc được chọn theo cân bằng chất lượng, chi phí, độ trễ; thiếu một trong ba dễ ra quyết định lệch.<br><strong>Vì sao các lựa chọn khác sai:</strong> Token output hay độ dài không nói về chất lượng; số model dùng không phải mục tiêu."},
  {"level": 2, "q": "Tool <code>refundOrder</code> của agent CSKH được hiện thực như dưới. Mục đích của thiết kế này là gì?<pre><code>async refundOrder(input: { orderId: string; amount: number; reason: string }) {\n  const req = await this.prisma.refundRequest.create({\n    data: { ...input, status: \"PENDING_APPROVAL\", requestedBy: \"agent\" },\n  });\n  await this.slack.notifyApprovers(req.id);\n  return `Đã tạo yêu cầu hoàn tiền ${req.id}, đang chờ nhân viên duyệt.`;\n}</code></pre>", "options": ["Agent chỉ tạo yêu cầu hoàn tiền chờ duyệt; con người phê duyệt mới thực thi, vì hoàn tiền không đảo ngược được", "Giúp agent hoàn tiền nhanh hơn", "Giảm số token của tool_result", "Bắt buộc theo Messages API"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Cổng phê duyệt nằm ngoài model, là kiểm soát tất định cho hành động có chi phí sai cao.<br><strong>Vì sao các lựa chọn khác sai:</strong> Thiết kế này làm chậm có chủ đích chứ không nhanh hơn; không nhằm giảm token; API không quy định cách bạn thực thi tool."},
  {"level": 2, "q": "Ba nhánh parallelization mất lần lượt 4 giây, 7 giây và 12 giây. Độ trễ tổng xấp xỉ bao nhiêu?", "options": ["23 giây", "Khoảng 12 giây, bằng nhánh chậm nhất (cộng thời gian gộp)", "4 giây", "7,7 giây (trung bình)"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Chạy song song thì tổng thời gian do nhánh chậm nhất quyết định.<br><strong>Vì sao các lựa chọn khác sai:</strong> 23 giây là khi chạy tuần tự; 4 giây là nhánh nhanh nhất; trung bình không phản ánh việc phải chờ mọi nhánh."},
  {"level": 2, "q": "Chuỗi 3 bước tuần tự, mỗi bước khoảng 5 giây. Đổi lại độ trễ khoảng 15 giây, chaining mang lại gì?", "options": ["Rẻ hơn một lần gọi trong mọi trường hợp", "Nhanh hơn một lần gọi", "Không cần prompt", "Mỗi bước đơn giản hơn nên chính xác hơn, dễ kiểm tra và sửa từng bước"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Chaining đổi độ trễ lấy độ chính xác và khả năng kiểm soát; phù hợp khi nhiệm vụ tách được thành các bước rõ ràng.<br><strong>Vì sao các lựa chọn khác sai:</strong> Chaining thường tốn nhiều token hơn chứ không chắc rẻ hơn; tuần tự thì chậm hơn; mỗi bước vẫn cần prompt riêng."},
  {"level": 2, "q": "Trong orchestrator–workers, bước tổng hợp (synthesizer) nhận kết quả từ 6 worker. Nhiệm vụ quan trọng của bước này là gì?", "options": ["Chỉ nối chuỗi các kết quả lại", "Chọn ngẫu nhiên một kết quả", "Gọi lại mọi worker lần nữa", "Gộp, loại trùng, phát hiện xung đột giữa các kết quả và tạo đầu ra nhất quán theo mục tiêu ban đầu"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Worker làm việc cô lập nên có thể trùng lặp hoặc mâu thuẫn; bước tổng hợp đảm bảo kết quả cuối đúng và gọn.<br><strong>Vì sao các lựa chọn khác sai:</strong> Nối chuỗi giữ nguyên trùng lặp và mâu thuẫn; chọn ngẫu nhiên bỏ phí công việc; gọi lại mọi worker tốn kém mà không giải quyết việc hợp nhất."},
  {"level": 2, "q": "Đoạn code kiểm duyệt nội dung dưới đây dùng 3 prompt khác nhau cho cùng một câu hỏi rồi lấy đa số. Đây là mẫu gì?<pre><code>const PROMPTS = [\n  \"Nội dung sau có vi phạm chính sách cộng đồng không?\",\n  \"Với vai trò kiểm duyệt viên nghiêm khắc, nội dung sau có cần gỡ không?\",\n  \"Nội dung sau có chứa lời lẽ thù ghét hoặc lừa đảo không?\",\n];\nconst verdicts = await Promise.all(PROMPTS.map((p) =&gt; judge(p, content)));\nconst flagged = verdicts.filter((v) =&gt; v.violates).length &gt;= 2;</code></pre>", "options": ["Sectioning", "Parallelization kiểu voting (với các prompt khác nhau cho cùng một nhiệm vụ)", "Routing", "Prompt chaining"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Cả 3 nhánh cùng trả lời một câu hỏi \"có vi phạm không\", chỉ khác góc nhìn prompt; kết quả được tổng hợp bằng đa số.<br><strong>Vì sao các lựa chọn khác sai:</strong> Sectioning chia thành các việc khác nhau; routing chọn một nhánh; chaining chạy tuần tự có phụ thuộc."},
  {"level": 2, "q": "Judge LLM chấm tiêu đề cao bất thường so với người duyệt. Cách cải thiện đáng tin nhất?", "options": ["Bảo judge \"hãy nghiêm khắc hơn\"", "Tăng ngưỡng dừng lên 10/10", "Bỏ judge, dùng độ dài làm điểm", "Viết rubric cụ thể có mô tả từng mức điểm, hiệu chỉnh judge trên một bộ mẫu đã được người chấm và theo dõi độ lệch"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Judge cần tiêu chí neo rõ ràng và được đối chiếu với nhãn của người để tin được.<br><strong>Vì sao các lựa chọn khác sai:</strong> Lời dặn chung chung không ổn định; ngưỡng 10 làm vòng lặp luôn chạy tối đa; độ dài không phản ánh chất lượng."},
  {"level": 2, "q": "Eval router trên 500 câu cho thấy: độ chính xác tổng 94%, nhưng 30% câu \"nghi lừa đảo\" bị xếp vào <code>simple</code>. Nhận định nào đúng?", "options": ["94% là đủ tốt, triển khai ngay", "Cần xem ma trận nhầm lẫn theo từng lớp; lỗi ở lớp rủi ro cao là không chấp nhận được dù độ chính xác tổng cao", "Chỉ cần tăng <code>max_tokens</code> của router", "Bỏ router, gửi tất cả tới Haiku"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Độ chính xác tổng che giấu lỗi ở lớp hiếm nhưng quan trọng; cần đo recall cho lớp rủi ro và có thể thêm nhánh riêng hoặc chuyển cho người.<br><strong>Vì sao các lựa chọn khác sai:</strong> Triển khai ngay bỏ qua rủi ro lớn; <code>max_tokens</code> không cải thiện phân loại; gửi tất cả tới Haiku làm vấn đề tệ hơn."},
  {"level": 2, "q": "Luồng xử lý đơn khiếu nại: phân loại, lấy dữ liệu đơn hàng từ database, soạn phản hồi theo mẫu. Các bước đã biết trước. Vì sao không nên dùng agent tự do?<pre><code>// apps/api/src/complaints/complaint.workflow.ts\nconst category = await this.classify(complaint.text);          // bước 1: Haiku + schema\nconst order = await this.prisma.order.findUnique({ where: { id: complaint.orderId } }); // bước 2: code\nconst reply = await this.draftReply(TEMPLATES[category], order, complaint); // bước 3: Claude</code></pre>", "options": ["Agent không truy cập được database", "Agent không viết được tiếng Việt", "Agent bị cấm dùng cho khiếu nại", "Workflow với các bước cố định rẻ hơn, nhanh hơn, dễ kiểm thử và cho kết quả ổn định hơn"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Khi đường đi đã biết, để model tự quyết chỉ thêm biến động và chi phí mà không thêm giá trị.<br><strong>Vì sao các lựa chọn khác sai:</strong> Agent truy cập được database qua tool; agent viết tiếng Việt tốt; không có quy định cấm nào như vậy."},
  {"level": 3, "q": "Ví điện tử nhận 30.000 câu hỏi/ngày, 70% là câu đơn giản (phí chuyển tiền, đổi mật khẩu), hiện tất cả đều gửi tới Opus. Mục tiêu: giảm chi phí mà không giảm chất lượng câu khó. Phương án tốt nhất?", "options": ["Chuyển toàn bộ sang Haiku ngay lập tức", "Xây multi-agent cho mỗi câu hỏi", "Thêm router Haiku có structured output; câu đơn giản sang Haiku kèm FAQ được cache, câu phức tạp sang Opus; chạy eval trên bộ câu có đáp án trước khi bật", "Giữ Opus nhưng giảm <code>max_tokens</code> còn 100"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Routing tận dụng việc input chia nhóm rõ ràng; eval đo được chất lượng và chi phí của cả hai cấu hình để quyết định bằng số liệu.<br><strong>Vì sao các lựa chọn khác sai:</strong> Chuyển hết sang Haiku có thể làm giảm chất lượng câu khó như khiếu nại hay nghi lừa đảo; multi-agent tăng chi phí; cắt <code>max_tokens</code> làm cụt câu trả lời."},
  {"level": 3, "q": "Kỹ sư đề xuất kiến trúc dưới đây để trích 5 trường từ hoá đơn PDF (số hoá đơn, ngày, mã số thuế, tổng tiền, VAT). Đánh giá nào đúng?<pre><code>// Đề xuất\nconst header = await agentA.run(pdf);   // số hoá đơn, ngày\nconst tax = await agentB.run(pdf);      // mã số thuế, VAT\nconst total = await agentC.run(pdf);    // tổng tiền\nconst merged = await coordinator.run({ header, tax, total });</code></pre>", "options": ["Hợp lý vì mỗi trường cần một chuyên gia", "Nên thêm agent thứ 4 để kiểm tra chéo", "Nên chuyển sang orchestrator–workers", "Quá phức tạp; một lời gọi với structured output (và kiểm tra bằng code) là đủ"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Đây là bẫy kinh điển: nhiệm vụ trích xuất có đầu vào và đầu ra rõ ràng không cần nhiều agent; schema đảm bảo định dạng, code kiểm tra tổng tiền và VAT.<br><strong>Vì sao các lựa chọn khác sai:</strong> Chia theo trường làm mỗi agent đọc lại toàn bộ PDF, nhân chi phí; thêm agent chỉ tăng thêm chi phí; không có việc chia nhỏ động nào cần orchestrator."},
  {"level": 3, "q": "Ý tưởng: agent tự đọc email khách hàng, trả lời và tự hoàn tiền tới 5 triệu đồng. Áp 4 câu hỏi kiểm tra agent, kết luận hợp lý nhất?", "options": ["Đủ 3/4 tiêu chí nên cho agent tự động hoàn toàn", "Phức tạp, giá trị, khả thi đều có, nhưng chi phí sai cao và không đảo ngược: cho agent soạn nháp và đề xuất hoàn tiền, con người duyệt trước khi gửi và thực thi", "Không dùng AI cho CSKH", "Dùng model mạnh nhất để không bao giờ sai"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Chỉ một câu \"không\" ở tiêu chí chi phí sai là đủ để thêm cổng phê duyệt; vẫn giữ phần lớn lợi ích nhờ agent soạn sẵn.<br><strong>Vì sao các lựa chọn khác sai:</strong> Tự động hoàn toàn bỏ qua rủi ro không đảo ngược; loại bỏ AI mất giá trị rõ ràng; không model nào bảo đảm không sai."},
  {"level": 3, "q": "Cần chuyển 300 file cấu hình sang định dạng mới; mỗi file có đặc thù khác nhau, repo có bộ test kiểm tra cấu hình và mọi thay đổi đi qua PR. Kiến trúc phù hợp?", "options": ["Một lời gọi API cho cả 300 file", "Chỉ dùng regex, không dùng AI", "Evaluator–optimizer với LLM judge thay cho test", "Agent (có thể chạy song song theo nhóm file), vì bước không định sẵn được, lỗi phát hiện bằng test và rollback được qua git"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Đủ 4 điều kiện: phức tạp, giá trị cao, khả thi, lỗi phát hiện và sửa được; chia nhóm để song song giảm thời gian.<br><strong>Vì sao các lựa chọn khác sai:</strong> 300 file không vừa và không phù hợp cho một lần gọi; regex không xử lý được đặc thù từng file; đã có test là phản hồi khách quan tốt hơn LLM judge."},
  {"level": 3, "q": "Bot review PR cho monorepo Turborepo. Danh sách package bị ảnh hưởng tính được bằng <code>turbo ls --affected</code>. Đồng nghiệp đề xuất dùng một LLM orchestrator để \"quyết định cần review package nào\". Lựa chọn tốt hơn?", "options": ["Luôn dùng orchestrator vì linh hoạt hơn", "Review toàn bộ monorepo mỗi PR", "Để code tính danh sách package bị ảnh hưởng rồi chạy review song song theo từng package (parallelization); chỉ dùng orchestrator khi việc chia không tính được bằng code", "Chỉ review package có nhiều dòng thay đổi nhất"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Khi cách chia xác định được một cách tất định, để code làm việc đó thì rẻ hơn, nhanh hơn và dễ đoán hơn để LLM quyết định.<br><strong>Vì sao các lựa chọn khác sai:</strong> Orchestrator thêm chi phí và biến động không cần thiết; review toàn repo lãng phí; chỉ review một package bỏ sót thay đổi."},
  {"level": 3, "q": "Trợ lý nghiên cứu phải đọc khoảng 50 nguồn (báo cáo, docs, blog) để tổng hợp đánh giá một công nghệ; một agent đọc hết sẽ tràn context. Kiến trúc hợp lý?", "options": ["Multi-agent: orchestrator chia nguồn cho các subagent đọc song song, mỗi subagent trả về tóm tắt có trích nguồn, orchestrator tổng hợp", "Một lời gọi với cả 50 nguồn", "Routing theo loại nguồn", "Voting 50 lần"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Công việc chia nhánh được và vượt context của một agent: đúng điều kiện để multi-agent đáng chi phí.<br><strong>Vì sao các lựa chọn khác sai:</strong> Một lời gọi không chứa nổi 50 nguồn; routing chỉ chọn nhánh chứ không tổng hợp; voting không phải bài toán ở đây."},
  {"level": 3, "q": "Ô chat trên Next.js có yêu cầu thời gian tới token đầu tiên dưới 2 giây. Đội muốn thêm evaluator–optimizer 3 vòng để nâng chất lượng mọi câu trả lời. Cách tiếp cận hợp lý?", "options": ["Không đặt vòng lặp chấm và sửa trên đường nóng; stream câu trả lời một lần gọi, và nếu cần thì chấm bất đồng bộ phía sau để cải thiện prompt", "Chạy 3 vòng rồi mới stream", "Chạy 3 vòng song song", "Bỏ streaming để người dùng chờ kết quả tốt nhất"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Evaluator–optimizer làm tăng độ trễ theo số vòng; ràng buộc độ trễ chặt nghĩa là chỉ dùng mẫu này ngoài luồng tương tác.<br><strong>Vì sao các lựa chọn khác sai:</strong> 3 vòng tuần tự vượt ngân sách độ trễ; vòng lặp phụ thuộc nhau nên không song song được; bỏ streaming làm trải nghiệm tệ hơn."},
  {"level": 3, "q": "Orchestrator refactor thường sinh 30–40 việc con cho thay đổi nhỏ, chi phí tăng vọt. Cải tiến nào phù hợp?<pre><code>const PLAN_SCHEMA = {\n  type: \"object\",\n  properties: {\n    tasks: {\n      type: \"array\",\n      items: {\n        type: \"object\",\n        properties: { goal: { type: \"string\" }, files: { type: \"array\", items: { type: \"string\" } } },\n        required: [\"goal\", \"files\"],\n        additionalProperties: false,\n      },\n    },\n  },\n  required: [\"tasks\"],\n  additionalProperties: false,\n};\n// + kiểm tra bằng code: if (plan.tasks.length &gt; 8) gộp hoặc từ chối kế hoạch</code></pre>", "options": ["Ràng buộc kế hoạch bằng schema (giới hạn số việc), hướng dẫn gộp việc nhỏ, và đặt ngân sách token cho cả nhiệm vụ", "Cho phép tới 100 việc con", "Bỏ bước lập kế hoạch, cho worker tự tìm việc", "Chạy tất cả worker trên Opus để làm nhanh hơn"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Orchestrator cần giới hạn rõ ràng; schema và ngân sách biến kỳ vọng thành ràng buộc code kiểm tra được.<br><strong>Vì sao các lựa chọn khác sai:</strong> Tăng giới hạn làm vấn đề tệ hơn; bỏ lập kế hoạch dẫn tới trùng lặp; model đắt hơn tăng chi phí thêm."},
  {"level": 3, "q": "Router CSKH có 2 nhãn <code>simple</code>/<code>complex</code>. Eval cho thấy câu \"nghi bị lừa đảo chuyển tiền\" thường bị xếp <code>simple</code>. Thiết kế lại nào phù hợp nhất?", "options": ["Giữ nguyên, vì tỉ lệ đúng tổng vẫn cao", "Bỏ router, chuyển hết sang nhân viên", "Tăng nhiệt độ của router", "Thêm nhãn riêng cho nhóm rủi ro cao (ví dụ <code>fraud</code>), luôn đi tới model mạnh kèm chuyển cho nhân viên, và đo recall riêng của nhãn này"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Nhóm rủi ro cao cần nhánh riêng với kiểm soát chặt; đo riêng giúp phát hiện khi chất lượng lớp này suy giảm.<br><strong>Vì sao các lựa chọn khác sai:</strong> Tỉ lệ đúng tổng che giấu lỗi ở lớp nguy hiểm; chuyển hết cho nhân viên bỏ phí lợi ích tự động hoá; nhiệt độ không phải cách sửa phân loại sai có hệ thống."},
  {"level": 3, "q": "Vòng evaluator–optimizer cho bài đăng Facebook: điểm judge dao động 5–9 cho cùng một bài giữa các lần chấm. Rubric gồm \"hay, cuốn hút, đúng chất\". Cách sửa tốt nhất?", "options": ["Chấm 10 lần rồi lấy trung bình cho mọi bài", "Viết rubric cụ thể có neo cho từng mức, tách tiêu chí đo được (≤ 120 từ, có hashtag, có CTA) ra kiểm tra bằng code, judge chỉ chấm tiêu chí cần phán đoán", "Bỏ judge, đăng luôn bản đầu", "Tăng số vòng tối đa lên 10"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Rubric mơ hồ tạo điểm ngẫu nhiên; tiêu chí rõ và kiểm tra tất định làm vòng lặp hội tụ và có ý nghĩa.<br><strong>Vì sao các lựa chọn khác sai:</strong> Chấm 10 lần nhân chi phí mà không sửa gốc rễ; bỏ judge mất kiểm soát chất lượng; thêm vòng với điểm ngẫu nhiên chỉ tốn thêm tiền."},
  {"level": 3, "q": "Agent dọn dẹp dữ liệu có thể chạy 30–90 phút, cần giữ trạng thái hội thoại qua nhiều lượt tool. Nên chạy trên hạ tầng AWS nào?", "options": ["ECS Fargate task (khởi chạy từ SQS hoặc API), lưu tiến độ vào database để tiếp tục khi lỗi", "Một Lambda duy nhất chạy cả vòng lặp", "Chạy trong route handler Next.js", "Chạy trong trình duyệt người dùng"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Agent chạy lâu vượt giới hạn 15 phút của Lambda và timeout của request HTTP; container trên Fargate phù hợp cho việc dài, có checkpoint.<br><strong>Vì sao các lựa chọn khác sai:</strong> Lambda bị giới hạn 15 phút; route handler bị timeout theo request; chạy trong trình duyệt lộ API key và không tin cậy."},
  {"level": 3, "q": "Pipeline phân tích hợp đồng: orchestrator cần suy luận phức tạp, 8 worker chỉ trích xuất điều khoản theo mẫu. Chọn model hợp lý?", "options": ["Tất cả dùng Haiku để rẻ nhất", "Orchestrator dùng <code>claude-opus-5</code>, worker dùng <code>claude-haiku-4-5</code>; mỗi vai trò giữ một model cố định để cache hiệu quả", "Tất cả dùng Opus để chắc chắn", "Mỗi lần gọi chọn ngẫu nhiên một model"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Chọn model theo độ khó của vai trò tối ưu chi phí; model cố định theo vai trò giữ cache vì cache tách theo model.<br><strong>Vì sao các lựa chọn khác sai:</strong> Haiku cho orchestrator có thể giảm chất lượng lập kế hoạch; Opus cho mọi worker lãng phí; chọn ngẫu nhiên phá cache và khó đo lường."},
  {"level": 3, "q": "Agent chính điều tra sự cố cần đọc 2 triệu token log trên CloudWatch nhưng chỉ cần kết luận. Thiết kế nào giữ context của agent chính gọn?", "options": ["Đưa hết log vào context agent chính", "Giao việc đọc log cho các subagent theo khung thời gian hoặc service, mỗi subagent trả về tóm tắt phát hiện có dẫn chứng", "Chỉ đọc 1.000 dòng đầu tiên", "Tăng <code>max_tokens</code> của agent chính"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Subagent cô lập phần đọc nặng; agent chính chỉ nhận kết quả cô đọng, đúng lý do chính đáng để dùng multi-agent.<br><strong>Vì sao các lựa chọn khác sai:</strong> 2 triệu token vượt context; đọc 1.000 dòng đầu dễ bỏ sót; <code>max_tokens</code> là giới hạn output, không mở rộng context."},
  {"level": 3, "q": "Bước kiểm tra bảo mật trong CI chạy trên mọi commit, ngân sách hạn chế. Đội muốn dùng voting 5 lần để tăng độ tin cậy. Thiết kế cân bằng nhất?", "options": ["Voting 5 lần cho mọi file mọi commit", "Bỏ kiểm tra bảo mật để tiết kiệm", "Chạy một lần cho mọi file; chỉ chạy voting với file bị gắn cờ hoặc thuộc vùng rủi ro cao (auth, thanh toán)", "Chỉ kiểm tra vào cuối quý"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Tập trung chi phí voting vào nơi sai lầm đắt nhất giữ ngân sách mà vẫn tăng độ tin cậy ở chỗ cần.<br><strong>Vì sao các lựa chọn khác sai:</strong> Voting toàn bộ nhân chi phí 5 lần; bỏ kiểm tra tăng rủi ro; kiểm tra theo quý bỏ lỡ lỗ hổng trong thời gian dài."},
  {"level": 3, "q": "Claude Code chạy headless trong GitHub Actions để sửa lỗi lint. File <code>.claude/settings.json</code> như dưới. Lệnh <code>git push --force</code> sẽ ra sao?<pre><code>{\n  \"permissions\": {\n    \"allow\": [\"Bash(pnpm lint:*)\", \"Bash(git:*)\", \"Edit\"],\n    \"deny\": [\"Bash(git push:*)\"]\n  }\n}</code></pre>", "options": ["Được chạy vì <code>Bash(git:*)</code> nằm trong allow", "Được chạy vì đang ở chế độ headless", "Bị chặn, vì quy tắc deny được ưu tiên hơn allow", "Claude Code sẽ hỏi người dùng trong CI"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Thứ tự ưu tiên là deny, rồi ask, rồi allow; khớp một quy tắc deny là bị chặn dù có allow rộng hơn.<br><strong>Vì sao các lựa chọn khác sai:</strong> Allow không ghi đè được deny; headless không bỏ qua permission; trong CI không có người để trả lời nên không dựa vào ask."},
  {"level": 3, "q": "Nhiệm vụ: tạo checklist onboarding cho nhân viên mới từ dữ liệu HR (phòng ban, vị trí, ngày bắt đầu), theo mẫu cố định 3 bước: lấy dữ liệu, chọn mẫu theo phòng ban, điền checklist. Kiến trúc phù hợp?", "options": ["Agent tự khám phá hệ thống HR", "Multi-agent mỗi phòng ban một agent", "Evaluator–optimizer 5 vòng", "Workflow: code lấy dữ liệu và chọn mẫu, một lời gọi Claude điền và cá nhân hoá checklist"], "answer": 3, "explain": "<strong>Vì sao đúng:</strong> Các bước biết trước và dữ liệu có cấu trúc: code làm phần tất định, LLM làm phần ngôn ngữ.<br><strong>Vì sao các lựa chọn khác sai:</strong> Agent tự khám phá thêm rủi ro truy cập dữ liệu và chi phí; multi-agent thừa; không có rubric nào cần lặp 5 vòng."},
  {"level": 3, "q": "Kết quả eval ba cấu hình cho tính năng tóm tắt ticket như dưới, mục tiêu tỉ lệ đạt ≥ 90% và p95 ≤ 5 giây. Chọn cấu hình nào?<pre><code>cấu hình     | đạt  | chi phí/ticket | p95\nsingle call  | 91%  | $0.004         | 2.1s\nchaining 3b  | 92%  | $0.011         | 4.8s\nagent        | 93%  | $0.060         | 19s</code></pre>", "options": ["Agent: vì tỉ lệ đạt cao nhất", "Single call: đạt mục tiêu với chi phí và độ trễ thấp nhất", "Chaining: vì cân bằng", "Không chọn, cần thêm multi-agent"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Nguyên tắc là chọn cấu hình đơn giản nhất thoả mục tiêu; 1–2 điểm phần trăm thêm không đáng chi phí gấp nhiều lần và vi phạm ngân sách độ trễ.<br><strong>Vì sao các lựa chọn khác sai:</strong> Agent vượt ngân sách p95; chaining đắt và chậm hơn mà không cần thiết; multi-agent càng xa mục tiêu độ trễ."},
  {"level": 3, "q": "Chuỗi 5 bước, mỗi bước độc lập đúng 95%. Không có cổng kiểm tra, tỉ lệ toàn chuỗi đúng xấp xỉ bao nhiêu và hàm ý là gì?", "options": ["95%, vì mỗi bước đều 95%", "Khoảng 99%", "Khoảng 77% (0,95^5); cần gate giữa các bước để bắt lỗi sớm hoặc giảm số bước", "Khoảng 25%"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Lỗi cộng dồn theo cấp số nhân qua các bước; cổng kiểm tra chặn lỗi trước khi lan và cho phép sửa cục bộ.<br><strong>Vì sao các lựa chọn khác sai:</strong> 95% bỏ qua việc lỗi cộng dồn; 99% ngược với thực tế; 25% tính sai."},
  {"level": 3, "q": "Sectioning 6 nhánh review cùng gửi một diff 60.000 token làm prefix chung, bắn đồng thời. Hoá đơn cho thấy cả 6 đều trả phí ghi cache. Tối ưu nào đúng?", "options": ["Mỗi nhánh dùng model khác nhau", "Đặt diff dùng chung lên đầu, giống hệt byte ở mọi nhánh; gửi một nhánh trước, đợi token đầu tiên rồi bắn 5 nhánh còn lại", "Đặt chỉ dẫn riêng của nhánh lên trước diff", "Tăng TTL lên 1 giờ"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Entry cache chỉ đọc được khi response đầu tiên đã bắt đầu stream; prefix chung giống hệt giúp 5 nhánh sau đọc cache.<br><strong>Vì sao các lựa chọn khác sai:</strong> Khác model thì không dùng chung cache; chỉ dẫn riêng đứng trước làm prefix khác nhau; TTL không giải quyết việc các request đồng thời."},
  {"level": 3, "q": "Agent phân tích dữ liệu được cấp tool như dưới. Rủi ro và cách thiết kế lại đúng?<pre><code>{\n  name: \"executeSql\",\n  description: \"Chạy câu SQL bất kỳ trên database production\",\n  input_schema: { type: \"object\", properties: { sql: { type: \"string\" } }, required: [\"sql\"] },\n}\n// handler: return prisma.$queryRawUnsafe(input.sql)</code></pre>", "options": ["Không có rủi ro vì model sẽ không viết lệnh xoá", "Chỉ cần thêm câu \"đừng xoá dữ liệu\" vào system prompt", "Tool quá rộng cho phép chạy SQL tuỳ ý (kể cả xoá dữ liệu); thay bằng các tool hẹp, chỉ đọc, có tham số kiểm tra, chạy bằng user database chỉ có quyền đọc", "Đổi tên tool thành <code>safeSql</code>"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Nguyên tắc quyền tối thiểu: giới hạn năng lực ở tầng tool và database, không trông vào lời dặn model; prompt injection có thể khiến model sinh lệnh nguy hiểm.<br><strong>Vì sao các lựa chọn khác sai:</strong> Không thể giả định model không bao giờ sinh lệnh nguy hiểm; lời dặn không phải ranh giới bảo mật; đổi tên không đổi quyền."},
  {"level": 3, "q": "Workflow sinh code cho endpoint NestJS mới. Nên dùng gì làm \"evaluator\" trong vòng evaluator–optimizer?<pre><code>for (let i = 0; i &lt; 3; i++) {\n  await writeFiles(await generate(spec, feedback));\n  const r = await exec(\"pnpm --filter @repo/api exec tsc --noEmit &amp;&amp; pnpm --filter @repo/api test\");\n  if (r.code === 0) break;\n  feedback = r.stderr.slice(-4000); // phần cuối log lỗi\n}</code></pre>", "options": ["Một LLM judge đọc code và cho điểm cảm tính", "Số dòng code sinh ra", "Kết quả <code>tsc --noEmit</code> và test (vitest/jest) chạy thật; lỗi compiler và test fail được đưa lại làm feedback", "Hỏi người dùng sau mỗi vòng"], "answer": 2, "explain": "<strong>Vì sao đúng:</strong> Phản hồi từ môi trường là khách quan và cụ thể, giúp vòng lặp hội tụ nhanh; LLM judge chỉ bổ sung cho các tiêu chí không kiểm tra tự động được.<br><strong>Vì sao các lựa chọn khác sai:</strong> Điểm cảm tính kém tin cậy hơn test; số dòng không phản ánh chất lượng; hỏi người dùng từng vòng làm mất tính tự động."},
  {"level": 3, "q": "Cần phân loại lại 200.000 ticket lịch sử trong đêm, không cần kết quả tức thời. Phương án tiết kiệm nhất?<pre><code>const batch = await client.messages.batches.create({\n  requests: tickets.map((t) =&gt; ({\n    custom_id: t.id,\n    params: {\n      model: \"claude-haiku-4-5\",\n      max_tokens: 50,\n      system: CLASSIFY_SYSTEM,\n      messages: [{ role: \"user\", content: t.text }],\n    },\n  })),\n});</code></pre>", "options": ["Agent đọc từng ticket và tự quyết định", "Mỗi ticket một request phân loại đơn giản, gửi qua Message Batches API (rẻ hơn khoảng 50%, xử lý bất đồng bộ)", "Gọi đồng bộ 200.000 request từ một Lambda", "Multi-agent chia 200.000 ticket cho 100 agent"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Việc đơn giản, lặp lại, không cần tương tác: single call qua Batches là rẻ nhất và không lo rate limit của gọi đồng bộ.<br><strong>Vì sao các lựa chọn khác sai:</strong> Agent là quá mức cho phân loại; gọi đồng bộ vướng giới hạn thời gian và rate limit; multi-agent tốn kém vô ích."},
  {"level": 3, "q": "Hệ thống multi-agent báo cáo sai nhưng không ai biết subagent nào gây lỗi. Cải tiến vận hành quan trọng nhất?", "options": ["Gắn trace ID cho cả nhiệm vụ, log nhiệm vụ giao, input, output và usage của từng subagent để truy vết", "Tăng số subagent để kết quả trung bình tốt hơn", "Chuyển sang model khác", "Tắt log để giảm chi phí"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Không quan sát được thì không debug được; trace theo nhiệm vụ cho biết lỗi xuất hiện ở bước nào.<br><strong>Vì sao các lựa chọn khác sai:</strong> Thêm subagent làm khó truy vết hơn; đổi model là đoán mò; tắt log làm vấn đề tệ hơn."},
  {"level": 3, "q": "Nền tảng hỗ trợ có 85% yêu cầu đi theo quy trình chuẩn, 15% là sự cố kỹ thuật lạ cần điều tra nhiều hệ thống. Kiến trúc hợp lý?", "options": ["Agent cho 100% yêu cầu", "Router ở đầu: yêu cầu chuẩn đi qua workflow cố định; sự cố lạ chuyển tới agent có tool điều tra và giới hạn quyền", "Workflow cho 100% yêu cầu, sự cố lạ trả lời \"không hỗ trợ\"", "Multi-agent cho mọi yêu cầu"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Kết hợp các mẫu theo đặc điểm từng nhóm: phần lớn rẻ và ổn định, phần khó có sự linh hoạt của agent.<br><strong>Vì sao các lựa chọn khác sai:</strong> Agent cho mọi yêu cầu tốn kém và kém ổn định; bỏ rơi sự cố lạ làm hỏng trải nghiệm; multi-agent cho mọi thứ quá đắt."},
  {"level": 3, "q": "Orchestrator nhận ticket của khách rồi chèn nguyên văn vào prompt cho các worker có quyền gọi tool <code>updateCustomer</code>. Rủi ro chính và biện pháp phù hợp?", "options": ["Prompt injection trong ticket lan sang worker; đánh dấu rõ nội dung khách là dữ liệu, giới hạn tool của worker ở mức tối thiểu, và bắt xác nhận cho thao tác ghi", "Không có rủi ro vì worker không nói chuyện với khách", "Chỉ cần dùng model mạnh hơn cho worker", "Mã hoá ticket bằng base64 trước khi chèn"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Dữ liệu không tin cậy đi qua nhiều tầng agent vẫn mang theo chỉ dẫn độc hại; quyền tối thiểu và cổng xác nhận chặn tác hại.<br><strong>Vì sao các lựa chọn khác sai:</strong> Worker vẫn đọc nội dung khách qua orchestrator; model mạnh hơn không phải ranh giới bảo mật; base64 không ngăn model giải mã và làm theo."},
  {"level": 3, "q": "Đội muốn agent tự merge PR của Dependabot khi CI xanh. Áp 4 câu hỏi kiểm tra, thiết kế hợp lý nhất?", "options": ["Tự merge mọi PR Dependabot", "Tự merge bản vá patch khi test xanh (lỗi phát hiện được, revert được); bản nâng major cần người review", "Không bao giờ tự động hoá", "Để agent tự quyết khi nào cần người"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Chi phí sai khác nhau theo loại cập nhật; tự động hoá phần rủi ro thấp, giữ con người ở phần có thể gây breaking change.<br><strong>Vì sao các lựa chọn khác sai:</strong> Tự merge major có thể phá vỡ production; từ chối hoàn toàn bỏ phí lợi ích rõ ràng; để agent tự đặt ranh giới là giao quyền kiểm soát cho chính thứ cần kiểm soát."},
  {"level": 3, "q": "Ban lãnh đạo muốn \"một agent tự trị xử lý mọi việc CSKH\" ngay quý này. Lộ trình khuyến nghị theo bài học?", "options": ["Bắt đầu với single call và routing cho các nhóm phổ biến, đo bằng eval; chỉ thêm agent cho nhóm việc phức tạp đã chứng minh cần, có cổng phê duyệt cho hành động nhạy cảm", "Xây ngay multi-agent tự trị cho mọi việc", "Chờ model thế hệ sau rồi mới làm", "Giao toàn quyền hoàn tiền cho agent từ đầu"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Tăng dần độ phức tạp theo bằng chứng giữ rủi ro và chi phí trong tầm kiểm soát, vẫn mang lại giá trị sớm.<br><strong>Vì sao các lựa chọn khác sai:</strong> Tự trị toàn phần ngay từ đầu rủi ro và khó debug; chờ đợi bỏ lỡ giá trị hiện có; giao quyền hoàn tiền không có kiểm soát vi phạm tiêu chí chi phí sai."},
  {"level": 3, "q": "Muốn Claude Code (headless) không bao giờ sửa file trong <code>packages/db/prisma/migrations/</code>, kể cả khi ai đó thêm quy tắc allow rộng. Cơ chế nào phù hợp?<pre><code>{\n  \"hooks\": {\n    \"PreToolUse\": [\n      {\n        \"matcher\": \"Edit|Write\",\n        \"hooks\": [{ \"type\": \"command\", \"command\": \"node .claude/hooks/block-migrations.mjs\" }]\n      }\n    ]\n  }\n}</code></pre>", "options": ["Hook PreToolUse cho <code>Edit|Write</code> kiểm tra đường dẫn và thoát với mã 2 để chặn; hook chạy trước bước kiểm tra permission", "Ghi chú \"đừng sửa migration\" trong CLAUDE.md là đủ", "Thêm quy tắc allow cho thư mục khác", "Đặt file migration ở chế độ chỉ đọc trong Git"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> Hook là kiểm soát tất định chạy trước permission, chặn bất kể quy tắc allow; CLAUDE.md chỉ là hướng dẫn cho model.<br><strong>Vì sao các lựa chọn khác sai:</strong> Hướng dẫn trong CLAUDE.md không bảo đảm; allow thư mục khác không chặn được thư mục này; Git không có khái niệm file chỉ đọc cho tiến trình cục bộ."},
  {"level": 3, "q": "Workflow gửi email xác nhận qua SQS + Lambda. Khi Lambda timeout và SQS gửi lại message, khách nhận 2 email giống nhau do bước Claude soạn và gửi chạy lại. Cách sửa đúng?<pre><code>// apps/worker/src/confirm-email.handler.ts\nexport const handler = async (event: SQSEvent) =&gt; {\n  for (const r of event.Records) {\n    const { ticketId } = JSON.parse(r.body);\n    const body = await draftEmail(ticketId); // gọi Claude\n    await ses.send(buildEmail(ticketId, body));\n  }\n};</code></pre>", "options": ["Dùng idempotency key (ví dụ <code>ticketId + step</code>) lưu trong database; bước nào đã hoàn tất thì bỏ qua khi message được gửi lại", "Tắt retry của SQS", "Tăng timeout và hy vọng không lặp lại", "Để Claude tự nhớ đã gửi email chưa"], "answer": 0, "explain": "<strong>Vì sao đúng:</strong> SQS bảo đảm giao ít nhất một lần; workflow phải idempotent ở từng bước có tác dụng phụ.<br><strong>Vì sao các lựa chọn khác sai:</strong> Tắt retry làm mất message khi lỗi thật; tăng timeout không loại bỏ khả năng gửi lại; model không có trạng thái giữa các lần gọi."},
  {"level": 3, "q": "Một bug nằm gọn trong module <code>billing</code> của <code>apps/api</code>, có test tái hiện. Đồng nghiệp đề xuất orchestrator với 5 worker. Lựa chọn tốt hơn?", "options": ["Orchestrator với 5 worker như đề xuất", "Một agent duy nhất có tool đọc, sửa file và chạy test của module đó", "Voting 5 agent sửa cùng lúc rồi chọn bản đa số", "Routing theo tên file"], "answer": 1, "explain": "<strong>Vì sao đúng:</strong> Phạm vi hẹp, một luồng làm việc liên tục; multi-agent chỉ đáng khi việc chia nhánh được hoặc vượt context.<br><strong>Vì sao các lựa chọn khác sai:</strong> 5 worker trên một module nhỏ gây xung đột sửa và tốn kém; voting cho việc sửa code tạo nhiều patch khó hợp nhất; routing không sửa được bug."}
];
